// Reads a File as a base64 data URL.
function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// Downscales/re-encodes an image file to keep it small enough for browser
// storage (localStorage has a small total quota). PDFs are left untouched
// aside from the size check, since they can't be re-compressed client-side.
async function compressImageFile(file, maxDim = 1600, quality = 0.72) {
  const dataUrl = await readFileAsDataURL(file);
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let { width, height } = img;
      if (width > maxDim || height > maxDim) {
        const scale = maxDim / Math.max(width, height);
        width = Math.round(width * scale);
        height = Math.round(height * scale);
      }
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL("image/jpeg", quality));
    };
    img.onerror = reject;
    img.src = dataUrl;
  });
}

/* ---------------- Product image storage (IndexedDB) ----------------
   Product photos are stored in IndexedDB rather than localStorage —
   localStorage caps out around 5MB total across the whole site, which
   isn't enough room for a real product catalog with multiple photos
   per product. IndexedDB gives each browser far more headroom. Each
   product just stores an array of image "keys" (strings); the actual
   image data lives in this separate store, loaded on demand. */
const IMG_DB_NAME = "pixelcrush_images";
const IMG_STORE = "images";

function openImageDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(IMG_DB_NAME, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(IMG_STORE)) {
        req.result.createObjectStore(IMG_STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function idbSetImage(key, dataUrl) {
  const db = await openImageDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(IMG_STORE, "readwrite");
    tx.objectStore(IMG_STORE).put(dataUrl, key);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}
async function idbGetImage(key) {
  const db = await openImageDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(IMG_STORE, "readonly");
    const req = tx.objectStore(IMG_STORE).get(key);
    req.onsuccess = () => resolve(req.result || null);
    req.onerror = () => reject(req.error);
  });
}
async function idbDeleteImage(key) {
  const db = await openImageDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(IMG_STORE, "readwrite");
    tx.objectStore(IMG_STORE).delete(key);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

/* ---------------- Product image storage (Cloudinary) ----------------
   Product photos now upload directly to Cloudinary instead of IndexedDB,
   so a photo uploaded on one device/browser shows up everywhere — the
   imageKeys array stores real Cloudinary URLs instead of per-browser
   IndexedDB keys. The idb* helpers above are kept in place (unused) in
   case any old-format keys still need to be read. */
const CLOUDINARY_CLOUD_NAME = "jguaxq83";
const CLOUDINARY_UPLOAD_PRESET = "pixelcrush_unsigned";

async function uploadToCloudinary(file) {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", CLOUDINARY_UPLOAD_PRESET);

  const response = await fetch(
    `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`,
    { method: "POST", body: formData }
  );

  if (!response.ok) {
    throw new Error("Cloudinary upload failed");
  }

  const data = await response.json();
  return data.secure_url; // permanent, cross-device image URL
}

// Each product image can be stored as either a plain string (a legacy
// pre-Cloudinary IndexedDB key, or a Cloudinary URL saved before colour
// tagging existed) or as { url, colorHex } once a colour has been
// assigned to that photo. This normalizes either shape into one form so
// every component that reads product images can treat them the same way.
function normImageKey(k) {
  if (typeof k === "string") {
    return { raw: k, url: /^https?:\/\//.test(k) ? k : null, colorHex: null };
  }
  return { raw: k.url, url: k.url, colorHex: k.colorHex || null };
}

